<?php
$symbol = match ($store['currency']) { 'USD' => 'US$', 'EUR' => '€', default => 'RD$' };
$number = (string) ($order['no_orden'] ?? $order['no_factura'] ?? $order['uid'] ?? '');
$state = mb_strtoupper(trim((string) ($order['estado'] ?? 'RECIBIDO')));
$equipment = trim((string) ($order['equipo'] ?? $order['marca_modelo'] ?? 'Equipo'));
$steps = ['RECIBIDO' => 1, 'DIAGNOSTICO' => 2, 'EN DIAGNOSTICO' => 2, 'EN_PROCESO' => 3, 'EN PROCESO' => 3, 'REPARANDO' => 3, 'LISTO' => 4, 'TERMINADO' => 4, 'FINALIZADO' => 4, 'ENTREGADO' => 5];
$currentStep = $steps[$state] ?? 1;
$date = static function (mixed $value): string {
    $value = trim((string) $value);
    if ($value === '') return 'Por confirmar';
    try { return (new DateTimeImmutable($value))->format('d/m/Y h:i A'); } catch (Throwable) { return $value; }
};
$money = static fn (mixed $value): string => number_format((float) $value, 2);
?>
