<main class="container content"><section class="panel progress"><?php foreach([1=>'Recibido',2=>'Diagnóstico',3=>'En reparación',4=>'Listo',5=>'Entregado'] as $index=>$label): ?><div class="step <?= $index<=$currentStep?'done':'' ?>"><span class="dot"><?= $index<$currentStep?'✓':$index ?></span><?= e($label) ?></div><?php endforeach; ?></section>
<div class="grid"><section class="panel section"><h2>Detalles del servicio</h2><div class="info-grid"><?php foreach([['Equipo',$equipment],['IMEI',$order['imei']??''],['Serial',$order['serial']??''],['Técnico',$order['tecnico']??''],['Fecha de entrada',$date($order['fecha_entrada']??$order['created_at']??'')],['Entrega estimada',$date($order['fecha_entrega']??'')],['Accesorios',$order['accesorios']??''],['Método de pago',$order['metodo_pago']??$order['metodopago']??'']] as [$label,$value]): if(trim((string)$value)==='')continue; ?><div class="info"><span><?= e($label) ?></span><strong><?= e($value) ?></strong></div><?php endforeach; ?></div>
<?php foreach([['Falla reportada',$order['fallas']??''],['Diagnóstico / reparación',$order['reparacion']??$order['observaciones']??''],['Piezas utilizadas o requeridas',$order['piezas']??'']] as [$label,$value]): if(trim((string)$value)==='')continue; ?><div class="block"><h3><?= e($label) ?></h3><p><?= e($value) ?></p></div><?php endforeach; ?></section>
